const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(d,opts)=>new Intl.DateTimeFormat('cs-CZ',{timeZone:'Europe/Prague',...opts}).format(new Date(d));
const key='vitkovice-vip-kiosk-v1';
let state={entries:[],results:{},closedMatches:{}};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&Array.isArray(saved.entries)&&saved.results&&typeof saved.results==='object')state=saved}catch{}
state.closedMatches=state.closedMatches&&typeof state.closedMatches==='object'?state.closedMatches:{};
let currentId=matches.some(m=>m.id===state.activeMatchId)?state.activeMatchId:(matches.find(m=>new Date(m.date)>new Date())?.id||matches.at(-1).id);
state.activeMatchId=currentId;
try{localStorage.setItem(key,JSON.stringify(state))}catch{}

let outcome='',screen='welcome',timer,lastActivity=Date.now();
let adminAuthenticated=false,testMode=false;
let practiceEntries=[];
let demo=null;
let celebration=null;
const WINNER_DURATION=5*60*1000;
const liveSnapshots=new Map(),liveErrors=new Map();
let liveRequest=null,lastLivePoll=0;
const ADMIN_PASSWORD='Digi2026';
const current=()=>matches.find(m=>m.id===currentId);
const started=m=>Date.now()>=new Date(m.date).getTime();
const closed=m=>Boolean(state.closedMatches[m.id]||state.results[m.id]);
const open=m=>started(m)&&!closed(m);

const canTip=m=>open(m)||(adminAuthenticated&&testMode);
const entries=id=>state.entries.filter(e=>e.matchId===id);
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;return true}catch{message('Uložení se nezdařilo. Požádej obsluhu o pomoc.');return false}}
function message(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function matchLine(m){return `Vítkovice Ridera <span class="versus">vs.</span> ${esc(m.opponent)}`}
function selectMatch(){return `<label class="field-label" for="match">Aktivní zápas pro celý kiosek</label><select id="match">${matches.map(m=>`<option value="${m.id}" ${m.id===currentId?'selected':''}>${fmt(m.date,{day:'numeric',month:'numeric',hour:'2-digit',minute:'2-digit'})} · ${esc(m.opponent)}</option>`).join('')}</select><p class="hint">Změna se uloží pro všechny další návštěvníky tohoto zařízení. Návštěvníci zápas nevybírají.</p>`}
function teamBadge(id){const team=HockeyTeams[id];if(!team)return '<span class="team-badge team-logo-fallback">HC</span>';return `<span class="team-badge" role="img" aria-label="Logo ${esc(team.name)}"><img class="team-logo" src="${esc(team.logo)}" alt="" data-remote-logo="${esc(team.remoteLogo)}"><span class="team-logo-fallback" hidden>${esc(team.short)}</span></span>`}
function matchCard(){const m=current();return `<section class="hero featured-match" aria-label="Zápas této VIP soutěže"><div class="hero-top"><span>DNEŠNÍ VIP SOUTĚŽ · ${m.round}. KOLO</span><span class="live" id="match-status">${closed(m)?'● TIPOVÁNÍ UZAVŘENO':started(m)?'● TIPOVÁNÍ OTEVŘENO':'● ČEKÁME NA ZAČÁTEK'}</span></div><div class="matchup"><div class="team">${teamBadge('vit')}<strong>VÍTKOVICE RIDERA</strong><small>DOMÁCÍ</small></div><span class="versus">VS</span><div class="team">${teamBadge(m.awayTeamId)}<strong>${esc(m.short)}</strong><small>HOSTÉ</small></div></div><div class="match-info">${fmt(m.date,{day:'numeric',month:'long',year:'numeric'})} &nbsp; / &nbsp; ${fmt(m.date,{hour:'2-digit',minute:'2-digit'})} &nbsp; / &nbsp; Domácí led</div><div class="countdown"><span id="countdown-label">${closed(m)?'Soutěž tohoto zápasu skončila':started(m)?'Tipujeme do konce 3. třetiny':'Tipování se otevře za'}</span><b id="countdown" role="timer">${countdownText(m)}</b></div></section>`}
function countdownText(m){if(closed(m))return 'TIPY UZAVŘENY';if(started(m))return 'ZAPOJ SE DO HRY';const seconds=Math.max(0,Math.ceil((new Date(m.date)-Date.now())/1000));return `${Math.floor(seconds/86400)} d : ${String(Math.floor(seconds/3600)%24).padStart(2,'0')} h : ${String(Math.floor(seconds/60)%60).padStart(2,'0')} m : ${String(seconds%60).padStart(2,'0')} s`}

function winnersMarkup(m){const result=state.results[m.id];if(!result)return '<p>Výsledek zatím není potvrzený. Po vyhodnocení zde vyhlásíme vítěze.</p>';const winners=Competition.evaluate(entries(m.id),result);return `<div class="final-score">${result.home} : ${result.away}</div><p>Výsledek po 60 minutách</p>${winners.length?`<span class="eyebrow">${winners[0].distance===0?'PŘESNÝ TIP':'NEJBLIŽŠÍ TIP'}</span><h1>${winners.length===1?'Gratulujeme vítězi!':'Gratulujeme vítězům!'}</h1><div class="winner-names">${winners.map(e=>`<div>${esc(e.name)} <small>tip ${e.home} : ${e.away}</small></div>`).join('')}</div><p class="prize">Výhra: ${esc(prizesFor(m.id)[0].title)} · cenu si vyzvedněte ve VIP zóně.</p>`:'<h1>Tento zápas nemá žádné tipy.</h1>'}`}
// Prizes are set by staff per match; until then the kiosk shows this default set.
const DEFAULT_PRIZES=[{title:'Podepsaný dres HC Vítkovice Ridera',detail:'Za přesný tip konečného skóre'},{title:'Dvě vstupenky do VIP zóny',detail:'Na další domácí zápas'},{title:'Klubový balíček z fanshopu',detail:'Šála, kšiltovka a puk'}];
const prizesFor=id=>Array.isArray(state.prizes?.[id])&&state.prizes[id].length?state.prizes[id]:DEFAULT_PRIZES;
const customPrizes=id=>Array.isArray(state.prizes?.[id])&&state.prizes[id].length>0;
function prizesPanel(m){const list=prizesFor(m.id);return `<aside class="side-panel prizes-panel" aria-label="Ceny pro vítěze"><span class="eyebrow">CO MŮŽEŠ VYHRÁT</span><h2>Ceny pro ${esc(m.short)}</h2><ol class="prize-list">${list.map((p,i)=>`<li><span class="prize-place">${i+1}.</span><div><strong>${esc(p.title)}</strong>${p.detail?`<small>${esc(p.detail)}</small>`:''}</div></li>`).join('')}</ol><p class="side-note">Vyhrává nejpřesnější tip po 60 minutách. Cenu si vítěz vyzvedne ve VIP zóně.</p></aside>`}
function participantsPanel(m){const list=entries(m.id).slice().sort((a,b)=>new Date(b.savedAt)-new Date(a.savedAt));const shown=list.slice(0,4);const more=list.length-shown.length;const moreText=more===1?'a další 1 soutěžící':more<5?`a další ${more} soutěžící`:`a dalších ${more} soutěžících`;const body=list.length?`<ul class="participant-list">${shown.map(e=>`<li><span class="participant-avatar">${esc(e.name.trim().charAt(0).toUpperCase()||'?')}</span><div><strong>${esc(e.name)}</strong><small>${e.savedAt&&!isNaN(new Date(e.savedAt))?fmt(e.savedAt,{hour:'2-digit',minute:'2-digit'}):'tip uložen'}</small></div><b>${e.home} : ${e.away}</b></li>`).join('')}</ul>${more>0?`<p class="side-note">… ${moreText}</p>`:''}`:`<div class="participants-empty"><span class="participants-empty-icon">🏒</span><strong>Zatím nikdo nehrál.</strong><p>Buď první a tipuj!</p>${open(m)?'<button class="primary" data-action="start">Tipnout jako první →</button>':`<small>${closed(m)?'Tipování tohoto zápasu je uzavřené.':'Tipování se otevře při začátku zápasu.'}</small>`}</div>`;return `<aside class="side-panel participants-panel" aria-label="Soutěžící"><div class="side-head"><div><span class="eyebrow">KDO UŽ TIPUJE</span><h2>Soutěžící</h2></div><span class="count-badge" id="participant-count">${list.length}</span></div>${body}</aside>`}
function refreshParticipants(){const panel=$('.participants-panel');if(!panel||screen!=='welcome')return;const m=current();if(String(entries(m.id).length)!==$('#participant-count')?.textContent)panel.outerHTML=participantsPanel(m)}
function prizeRowsMarkup(rows){return rows.map((p,i)=>`<div class="prize-row"><span class="prize-place">${i+1}.</span><input type="text" name="title" maxlength="80" placeholder="Cena (např. Podepsaný dres)" value="${esc(p.title||'')}" aria-label="Cena ${i+1}"><input type="text" name="detail" maxlength="100" placeholder="Doplněk (volitelné)" value="${esc(p.detail||'')}" aria-label="Poznámka k ceně ${i+1}"><button type="button" class="text-button" data-action="prize-remove" data-index="${i}" aria-label="Odebrat cenu ${i+1}">×</button></div>`).join('')}
function readPrizeRows(){return [...document.querySelectorAll('#prize-rows .prize-row')].map(row=>({title:row.querySelector('[name=title]').value.trim().replace(/\s+/g,' '),detail:row.querySelector('[name=detail]').value.trim().replace(/\s+/g,' ')}))}
function prizesAdmin(m){const custom=customPrizes(m.id);return `<section class="admin-preview prizes-admin"><h2>Ceny pro tento zápas</h2><p class="hint">${custom?'Ceny upravené obsluhou. Zobrazují se na úvodní obrazovce a při vyhlášení vítěze.':'Zatím výchozí ceny. Uprav je pro tento zápas — každý zápas má vlastní seznam.'}</p><form id="prizes-form"><div id="prize-rows">${prizeRowsMarkup(prizesFor(m.id))}</div><div class="prize-actions"><button type="button" class="text-button" data-action="prize-add">+ Přidat cenu</button><button class="primary">Uložit ceny →</button></div></form></section>`}
function addPrizeRow(){const rows=readPrizeRows();if(rows.length>=6){message('Maximálně šest cen na zápas.');return}rows.push({title:'',detail:''});$('#prize-rows').innerHTML=prizeRowsMarkup(rows);[...document.querySelectorAll('#prize-rows [name=title]')].at(-1)?.focus()}
function removePrizeRow(index){const rows=readPrizeRows();rows.splice(index,1);$('#prize-rows').innerHTML=prizeRowsMarkup(rows)}
function savePrizes(){if(!adminAuthenticated)return;const m=current();const rows=readPrizeRows().filter(p=>p.title);if(!rows.length){message('Zadej alespoň jednu cenu.');return}if(persist({...state,prizes:{...(state.prizes||{}),[m.id]:rows}})){message(`Ceny pro zápas s ${m.short} jsou uložené.`);staff()}}
function welcome(){screen='welcome';outcome='';const m=current();$('#main').innerHTML=`<section class="attract"><img class="attract-logo" src="${logo}" alt="HC Vítkovice Ridera"><span class="eyebrow">EXKLUZIVNĚ PRO HOSTY VIP ZÓNY</span><h1>Na ledě tým.<br>Ve hře ty.</h1><p>Tipni skóre. Užij si zápas. Vyhraj cenu.</p><div class="attract-grid"><div class="attract-center">${matchCard()}<button class="touch-start" data-action="start">☝ <span>Dotkni se obrazovky<small>${open(m)?'a zapoj se do tipovací soutěže':'a prohlédni si dnešní zápas'}</small></span> →</button><button class="text-button" data-action="winners">Průběžné pořadí a vítězové →</button></div><div class="side-panels">${prizesPanel(m)}${participantsPanel(m)}</div></div>${clubNav()}<div class="attract-bottom">JEDEN TÝM. JEDNO SRDCE. <span>HC VÍTKOVICE RIDERA</span></div></section>`}
function form(){screen='form';outcome='';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Úvod</button><span class="eyebrow">VIP TIPOVACÍ SOUTĚŽ</span><button class="text-button" data-action="rules">Pravidla</button></div><section class="kiosk-card"><span class="eyebrow">${testMode?'ADMIN · ZKUŠEBNÍ TIP':open(m)?'TVŮJ TIP NA DOMÁCÍ ZÁPAS':closed(m)?'TIPOVÁNÍ UZAVŘENO':'TIPOVÁNÍ SE BRZY OTEVŘE'}</span><h1>${matchLine(m)}</h1><p class="hint">${fmt(m.date,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · Tipujeme po 60 minutách, bez prodloužení a nájezdů.</p>${matchCard()}${testMode?'<div class="notice test-notice">ZKUŠEBNÍ REŽIM · Tip se nezapočítá do soutěže. Můžeš vyzkoušet celý formulář i před začátkem zápasu.<br><button type="button" class="text-button" data-action="admin-panel">Ukončit test a vrátit se do administrace →</button></div>':''}${!canTip(m)?`<div class="notice">${closed(m)?'Tipování tohoto zápasu skončilo. Podívej se na výsledky a vítěze.':'Tipování se otevře při plánovaném začátku zápasu a poběží do konce 3. třetiny.'}</div><button class="primary" data-action="winners">Průběžné pořadí a vítězové →</button>`:`<form id="entry-form" autocomplete="off"><label class="field-label" for="guest-name">1. Jak se jmenuješ?</label><input id="guest-name" name="name" type="text" minlength="2" maxlength="60" required autocomplete="off" placeholder="Tvé jméno a příjmení"><label class="field-label">2. Jak zápas dopadne?</label><div class="choices">${[['1','Vyhrají Vítkovice'],['X','Remíza'],['2','Vyhrají hosté']].map(([v,label])=>`<button type="button" data-outcome="${v}" class="choice" aria-pressed="false"><b>${v}</b>${label}</button>`).join('')}</div><div class="form-row"><div><label class="field-label" for="home-score">3. Tipni přesné skóre</label><div class="score"><div><input id="home-score" aria-label="Góly Vítkovic" type="number" inputmode="numeric" min="0" max="30" required placeholder="0"><small>Vítkovice</small></div><span>:</span><div><input id="away-score" aria-label="Góly soupeře" type="number" inputmode="numeric" min="0" max="30" required placeholder="0"><small>Hosté</small></div></div></div><div><label class="field-label" for="goals">4. Kolik padne gólů? <small>(volitelné)</small></label><select id="goals"><option value="">Bez dalšího tipu</option><option value="under">0 až 5 gólů (pod 5,5)</option><option value="over">6 a více gólů (nad 5,5)</option></select></div></div><p class="hint">Jméno použijeme k vyhlášení vítěze na této obrazovce. Jeden tip na jméno a zápas na tomto kiosku. Při shodě vyhrávají všichni stejně úspěšní.</p><div class="submit-row"><button type="button" class="text-button" data-action="rules">Jak vybíráme vítěze?</button><button class="primary">${testMode?'Odeslat zkušební tip':'Potvrdit můj tip'} →</button></div></form>`}</section>`}
function resultScreen(){screen='winners';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Úvod</button><span class="eyebrow">VIP TIPOVACÍ SOUTĚŽ</span><button class="text-button" data-action="rules">Pravidla</button></div><section class="kiosk-card results-screen">${matchCard()}<h2>${matchLine(m)}</h2><div id="live-board-content">${realBoardMarkup()}</div>${state.results[m.id]?winnersMarkup(m)+'<button class="primary" data-action="award">Zobrazit pohár →</button>':''}<button class="primary" data-action="home">Zpět na úvod →</button></section>`;pollLive()}
function rankingTable(tips,snapshot,final=false){
  const ranked=snapshot?Competition.rank(tips,snapshot):tips.map(e=>({...e,position:null,distance:null}));
  if(!ranked.length)return '<div class="empty">Zatím tu není žádný tip. Zapoj se do soutěže a najdi zde své jméno.</div>';
  return `<div class="table-scroll"><table class="score-table"><caption>${final?'Konečné pořadí tipů':'Jak si stojí tipy v tomto zápase'}</caption><thead><tr><th scope="col">Pořadí</th><th scope="col">Jméno</th><th scope="col">Tip</th><th scope="col">Odchylka</th><th scope="col">Stav</th></tr></thead><tbody>${ranked.map(e=>`<tr class="${e.position===1?'leading-row':''}"><td>${e.position?e.position+'.':'—'}</td><th scope="row">${esc(e.name)}</th><td class="table-score">${e.home} : ${e.away}</td><td>${e.distance===null?'—':e.distance}</td><td>${e.position===1?(final?'Vítěz':e.distance===0?'Průběžný lídr · přesný tip':'Průběžný lídr'):snapshot?'Ve hře':'Čeká na skóre'}</td></tr>`).join('')}</tbody></table></div><p class="hint">Odchylka = součet rozdílů obou skóre. Menší je lepší. Při shodě rozhoduje správný doplňkový tip na góly; při další shodě mají tipy stejné pořadí.</p>`;
}
function realBoardMarkup(){
  const m=current(),final=state.results[m.id],raw=liveSnapshots.get(m.id);
  const stale=raw&&Date.now()-Date.parse(raw.updatedAt)>90000;
  const snapshot=final||(!liveErrors.has(m.id)&&!stale?raw:null);
  const status=final?'Potvrzený výsledek po 60 minutách':snapshot?`${LiveMatch.phases[snapshot.phase]} · ${snapshot.clock}`:raw?'Aktualizace skóre je nedostupná. Pořadí nyní nepočítáme.':(liveErrors.get(m.id)||'Zdroj živých výsledků zatím není připojený.');
  return `<div class="live-score-panel"><span class="eyebrow">${final?'KONEČNÝ VÝSLEDEK':snapshot?'PRŮBĚŽNÝ STAV':'ČEKÁME NA AKTUÁLNÍ DATA'}</span><div class="live-score">${snapshot?`${snapshot.home} : ${snapshot.away}`:'— : —'}</div><p>${esc(status)}</p>${raw?`<small>Poslední přijatá aktualizace: ${fmt(raw.updatedAt,{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</small>`:''}</div>${!final?'<div class="notice">Průběžný lídr není konečný vítěz. Pořadí se mění s každým gólem; vítěze vyhlásíme až po potvrzení výsledku.</div>':''}${rankingTable(entries(m.id),snapshot,Boolean(final))}`;
}
function refreshBoard(){if(screen==='winners'&&$('#live-board-content')){const markup=realBoardMarkup();if($('#live-board-content').innerHTML!==markup)$('#live-board-content').innerHTML=markup}}
async function pollLive(){
  const id=currentId;
  if(demo||liveRequest||!started(current())||state.results[id]||Date.now()-lastLivePoll<15000)return;
  lastLivePoll=Date.now();const controller=new AbortController();liveRequest=controller;
  const timeout=setTimeout(()=>controller.abort(),8000);
  try{
    const response=await fetch(`/api/live?matchId=${encodeURIComponent(id)}`,{cache:'no-store',signal:controller.signal});
    if(!response.ok)throw Error(response.status===503||response.status===404?'Zdroj živých výsledků zatím není připojený.':'Aktualizace skóre je dočasně nedostupná.');
    const snapshot=LiveMatch.validateSnapshot(await response.json(),id,Date.now());
    if(demo)return;
    const previous=liveSnapshots.get(id);
    if(previous&&Date.parse(snapshot.updatedAt)<Date.parse(previous.updatedAt))throw Error('Čekáme na novější skóre.');
    liveSnapshots.set(id,snapshot);liveErrors.delete(id);
    if(snapshot.phase==='regulation_end'&&!state.closedMatches[id])persist({...state,closedMatches:{...state.closedMatches,[id]:snapshot.updatedAt}});
  }catch(error){liveErrors.set(id,error.message||'Aktualizace skóre je nedostupná.')}
  finally{clearTimeout(timeout);liveRequest=null;if(currentId===id)refreshBoard()}
}
function startDemo(){if(!adminAuthenticated)return;if(liveRequest)liveRequest.abort();testMode=false;demo=LiveMatch.createDemo(currentId);demoScreen()}
function demoScreen(){
  if(!adminAuthenticated||!demo)return;screen='demo';
  const step=demo.steps[demo.index],final=step.phase==='regulation_end';
  const winners=final?Competition.evaluate(demo.tips,step):[];
  $('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="demo-exit">← Administrace</button><span class="eyebrow">DEMO · SIMULOVANÝ ZÁPAS</span><button class="text-button" data-action="home">Ukončit a zamknout</button></div><section class="kiosk-card results-screen"><div class="notice test-notice">DEMOVERZE · Náhodná jména, ukázkové tipy a simulované skóre. Žádná data skutečné soutěže se nemění.</div><h1>${matchLine(current())}</h1><div class="live-score-panel"><span class="eyebrow">${LiveMatch.phases[step.phase]}</span><div class="live-score">${step.home} : ${step.away}</div><p>${step.clock} · ${esc(step.note)}</p></div><div class="demo-progress"><span style="width:${100*demo.index/(demo.steps.length-1)}%"></span></div><div class="demo-controls"><button data-action="demo-toggle" ${final?'disabled':''}>${demo.playing?'Pozastavit':'Pokračovat'}</button><button data-action="demo-next" ${final?'disabled':''}>Další událost →</button><button data-action="demo-restart">Spustit znovu</button></div><p class="hint">Událost ${demo.index+1} / ${demo.steps.length} · automatický posun každých 5 sekund</p>${rankingTable(demo.tips,step,final)}${final?`<div class="demo-winners"><span class="eyebrow">KONEČNÝ VÝSLEDEK DEMOVERZE</span><h1>${winners.length===1?'Gratulujeme vítězi!':'Gratulujeme vítězům!'}</h1>${winners.map(e=>`<h2>${esc(e.name)}</h2>`).join('')}<p>Cenu si vyzvedněte ve VIP zóně.</p></div>`:'<p class="hint">Zvýrazněné jméno je pouze průběžný lídr. S dalším gólem se může změnit.</p>'}</section>`;
}
function advanceDemo(){if(!adminAuthenticated||!demo||demo.index>=demo.steps.length-1)return;demo.index++;demo.lastStepAt=Date.now();if(demo.index===demo.steps.length-1)demo.playing=false;demoScreen();if(demo.index===demo.steps.length-1)showCelebration(true)}

function showCelebration(isDemo=false){
  const result=isDemo?demo?.steps[demo.index]:state.results[currentId];
  if(!result||(isDemo&&result.phase!=='regulation_end'))return false;
  const winners=Competition.evaluate(isDemo?demo.tips:entries(currentId),result);
  if(!winners.length)return false;
  celebration={isDemo,expiresAt:Date.now()+WINNER_DURATION};screen='celebration';
  awardBackground(true);
  if(!isDemo){adminAuthenticated=false;testMode=false;practiceEntries=[]}
  const trophy='<svg class="winner-trophy" viewBox="0 0 200 220" role="img" aria-label="Vítězný pohár"><defs><linearGradient id="cup-gold" x2="1" y2="1"><stop stop-color="#fff2b3"/><stop offset=".5" stop-color="#e8bd5e"/><stop offset="1" stop-color="#a36a1d"/></linearGradient></defs><path d="M55 30H25v35c0 30 25 45 48 45M145 30h30v35c0 30-25 45-48 45" fill="none" stroke="#dfb45c" stroke-width="12"/><path d="M50 15h100v65c0 35-22 55-50 55S50 115 50 80zM91 130h18v40H91zM65 170h70v17H65zM45 187h110v20H45z" fill="url(#cup-gold)"/><path d="m100 42 8 17 19 3-14 13 3 19-16-9-16 9 3-19-14-13 19-3z" fill="#fff4c5"/></svg>';
  $('#main').innerHTML=`<section class="winner-celebration" role="dialog" aria-modal="true" aria-labelledby="winner-title"><div class="winner-glow"></div><div class="winner-content">${isDemo?'<span class="demo-award-label">DEMOVERZE · UKÁZKOVÉ VYHLÁŠENÍ</span>':''}${trophy}<span class="eyebrow">${winners[0].distance===0?'PŘESNÝ TIP':'NEJBLIŽŠÍ TIP'}</span><h1 id="winner-title">${winners.length===1?'Gratulujeme vítězi!':'Gratulujeme vítězům!'}</h1><div class="celebration-names">${winners.map(w=>`<div>${esc(w.name)}<small>Tip ${w.home} : ${w.away} · odchylka ${w.distance}</small></div>`).join('')}</div><p class="celebration-result">Výsledek zápasu ${result.home} : ${result.away} po 60 minutách</p><p class="celebration-prize">Cenu si vyzvedněte ve VIP zóně.</p></div><button class="celebration-dismiss" id="winner-dismiss" data-action="celebration-dismiss"><span>Dotkni se obrazovky pro zavření poháru</span></button></section>`;
  $('#winner-dismiss').focus();return true;
}
function dismissCelebration(){
  if(!celebration)return;
  awardBackground(false);
  const wasDemo=celebration.isDemo;celebration=null;lastActivity=Date.now();
  if(wasDemo&&demo&&adminAuthenticated)demoScreen();else resultScreen();
}
function awardBackground(inert){document.querySelectorAll('body > header, body > footer, #partners-strip, #admin-access, #dialog').forEach(node=>node.inert=inert)}

function thanks(entry){screen='thanks';$('#main').innerHTML=`<section class="attract confirmation"><span class="confirmation-icon">✓</span><span class="eyebrow">${testMode?'ZKUŠEBNÍ TIP JE V POŘÁDKU':'TIP JE ULOŽENÝ'}</span><h1>Díky za tip,<br>${esc(entry.name)}!</h1><p>${matchLine(current())}</p><div class="final-score">${entry.home} : ${entry.away}</div><p>${testMode?'Test proběhl úspěšně.<br>Tento tip neovlivní soutěž ani vítěze.':'Po zápase vyhlásíme vítěze.<br>Cenu si vítěz vyzvedne ve VIP zóně.'}</p>${testMode?'<button class="primary" data-action="admin-panel">Zpět do administrace →</button>':''}<button class="touch-start" data-action="home">${testMode?'Ukončit test a zamknout administraci':'Další návštěvník'} →</button><small>Za 12 sekund se obrazovka vrátí na úvod.</small></section>`;setTimeout(()=>{if(screen==='thanks')home()},12000)}
function rules(){ $('#dialog-content').innerHTML='<span class="eyebrow">PRAVIDLA VIP SOUTĚŽE</span><h1>Jak vybereme vítěze?</h1><ol><li>Vyber výsledek 1 / X / 2 a přesné skóre po 60 minutách. Remíza je platný tip.</li><li>Vyhrává přesné skóre. Pokud jej nikdo netrefí, vyhrává nejmenší součet odchylek obou skóre. Pro výsledek 2:1 má tip 3:1 odchylku 1.</li><li>Při stejné odchylce rozhodne správný doplňkový tip na počet gólů (0–5 / 6 a více). I mezi přesnými tipy.</li><li>Při další shodě vyhlašujeme všechny společné vítěze. Rozdělení cen zajistí obsluha VIP zóny.</li><li>Jeden tip na jméno a utkání na tomto zařízení. Tip nelze po potvrzení měnit. Jméno není ověřená totožnost.</li><li>Tipování začíná v plánovaný začátek zápasu a končí po 3. třetině. Konec 3. třetiny zde potvrzuje obsluha, živý stav utkání zatím není připojený. Při odložení pořadatel musí termín nejprve opravit; automatické změny zatím nejsou připojené.</li></ol><p>Místní prototyp: tipy zůstávají v tomto prohlížeči. Výsledek ručně potvrzuje obsluha. Ceny a finální pravidla schvaluje pořadatel.</p>';$('#dialog').showModal()}
function staff(){awardBackground(false);celebration=null;demo=null;if(!adminAuthenticated){welcome();adminLogin();return}testMode=false;screen='staff';const m=current();$('#main').innerHTML=`<div class="kiosk-head"><button class="text-button" data-action="home">← Kiosek</button><span class="eyebrow">OBSLUHA · MÍSTNÍ PROTOTYP</span></div><section class="kiosk-card"><h1>Administrace VIP zóny</h1><div class="notice">Místní heslová brána prototypu. Pro ostrý provoz je potřeba serverové přihlášení obsluhy. Výsledek zadejte až po skončení základní hrací doby.</div><section class="admin-preview"><h2>Demoverze zápasu</h2><p class="hint">Tři ukázkové tipy, průběh všech třetin, měnící se pořadí a vyhlášení vítěze.</p><button class="primary" data-action="demo-start">Spustit demo zápasu →</button><hr class="admin-divider"><h2>Vyzkoušej tipování</h2><p class="hint">Otevři formulář i před začátkem zápasu. Zkušební tipy neovlivní skutečnou soutěž.</p><button class="primary" data-action="test-start">Spustit zkušební tipování →</button><p class="hint">${practiceEntries.length} zkušebních tipů během tohoto přihlášení</p></section>${selectMatch()}${prizesAdmin(m)}${started(m)&&!closed(m)?'<button class="primary close-competition" data-action="close-tipping">Konec 3. třetiny — uzavřít tipy</button><p class="hint">Stiskněte při skončení třetí třetiny, před zadáním výsledku. Poté už kiosek nepřijme žádný tip.</p>':''}<p class="hint">${entries(m.id).length} přijatých tipů na tomto zařízení</p>${state.results[m.id]?`<h2>Potvrzený výsledek: ${state.results[m.id].home} : ${state.results[m.id].away}</h2><p class="hint">Výsledek je uzamčený. Vyhlášení vítězů najdete v kiosku.</p><button class="primary" data-action="winners">Zobrazit vítěze →</button>`:`<form id="result-form"><label class="field-label">Potvrzený výsledek po 60 minutách</label><div class="score"><input id="result-home" aria-label="Skutečné góly Vítkovic" type="number" min="0" max="30" inputmode="numeric" required><span>:</span><input id="result-away" aria-label="Skutečné góly soupeře" type="number" min="0" max="30" inputmode="numeric" required></div><label class="confirm-label"><input id="result-confirm" type="checkbox" required> Ověřil/a jsem výsledek po 60 minutách a chci vyhlásit vítěze.</label><button class="primary" ${!closed(m)?'disabled':''}>Potvrdit výsledek a vyhodnotit →</button><p class="hint">${!closed(m)?'Nejdříve uzavřete tipování tlačítkem Konec 3. třetiny.':'Tipování je uzavřené. Potvrďte výsledek po dohrání 60 minut.'}</p></form>`}</section>`}
function submitEntry(){const m=current();if(!canTip(m)){message(closed(m)?'Tipování je už uzavřené.':'Tipování se otevře při začátku zápasu.');form();return}const h=$('#home-score').value,a=$('#away-score').value;const entry={id:crypto.randomUUID(),matchId:m.id,name:$('#guest-name').value.trim().replace(/\s+/g,' '),outcome,home:h===''?null:Number(h),away:a===''?null:Number(a),goals:$('#goals').value,savedAt:new Date().toISOString()};const error=Competition.validate(entry);if(error){message(error);return}const normalized=s=>s.normalize('NFKC').toLocaleLowerCase('cs-CZ');if(!testMode&&entries(m.id).some(e=>normalized(e.name)===normalized(entry.name))){message('Na toto jméno už je pro tento zápas tip uložený. Při shodě jmen se obrať na obsluhu.');return}if(testMode&&adminAuthenticated){practiceEntries.push(entry);thanks(entry);return}if(persist({...state,entries:[...state.entries,entry]}))thanks(entry)}
function submitResult(){if(!adminAuthenticated)return;const m=current();if(!closed(m)||state.results[m.id]){message('Tento zápas teď nelze vyhodnotit.');return}const h=$('#result-home').value,a=$('#result-away').value;const result={home:h===''?null:Number(h),away:a===''?null:Number(a),confirmedAt:new Date().toISOString()};if(!Competition.validScore(result.home)||!Competition.validScore(result.away)||!$('#result-confirm').checked){message('Vyplň skóre a potvrď ověření výsledku.');return}if(persist({...state,results:{...state.results,[m.id]:result}})){resultScreen();showCelebration(false)}}
function home(){awardBackground(false);celebration=null;demo=null;adminAuthenticated=false;testMode=false;practiceEntries=[];currentId=state.activeMatchId;lastActivity=Date.now();if($('#dialog').open)$('#dialog').close();if(location.hash)history.replaceState(null,'',location.pathname+location.search);welcome()}
$('#main').addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='entry-form')submitEntry();if(event.target.id==='result-form')submitResult();if(event.target.id==='prizes-form')savePrizes()});
$('#main').addEventListener('change',event=>{if(event.target.id==='match'&&screen==='staff'&&adminAuthenticated&&matches.some(m=>m.id===event.target.value)){if(persist({...state,activeMatchId:event.target.value})){currentId=event.target.value;staff()}else event.target.value=currentId}});
$('#main').addEventListener('click',event=>{const b=event.target.closest('[data-outcome]');if(b){outcome=b.dataset.outcome;document.querySelectorAll('[data-outcome]').forEach(el=>{el.classList.toggle('selected',el.dataset.outcome===outcome);el.setAttribute('aria-pressed',String(el.dataset.outcome===outcome))})}const player=event.target.closest('[data-player-id]');if(player)playerScreen(player.dataset.playerId);const group=event.target.closest('[data-player-group]');if(group)playersScreen(group.dataset.playerGroup);const era=event.target.closest('[data-era]');if(era)achievementsScreen(era.dataset.era);const prizeButton=event.target.closest('[data-action=prize-add],[data-action=prize-remove]');if(prizeButton){if(prizeButton.dataset.action==='prize-add')addPrizeRow();else removePrizeRow(Number(prizeButton.dataset.index));return}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='award')showCelebration(false);if(action==='achievements')achievementsScreen();if(action==='players')playersScreen();if(action==='celebration-dismiss')dismissCelebration();if(action==='demo-start')startDemo();if(action==='demo-next'&&adminAuthenticated)advanceDemo();if(action==='demo-toggle'&&adminAuthenticated&&demo&&demo.index<demo.steps.length-1){demo.playing=!demo.playing;demo.lastStepAt=Date.now();demoScreen()}if(action==='demo-restart'&&adminAuthenticated)startDemo();if(action==='demo-exit'&&adminAuthenticated)staff();if(action==='test-start'&&adminAuthenticated){testMode=true;form()}if(action==='admin-panel'&&adminAuthenticated)staff();if(action==='close-tipping'&&adminAuthenticated&&screen==='staff'&&started(current())&&!closed(current())){if(persist({...state,closedMatches:{...state.closedMatches,[currentId]:new Date().toISOString()}}))staff()}if(action==='start')form();if(action==='home')home();if(action==='winners')resultScreen();if(action==='rules')rules()});
// Touch keyboard for the staff login: ASCII letters and digits only, Shift for capitals.
let keyboardShift=false;
const KEYBOARD_ROWS=['1234567890','qwertyuiop','asdfghjkl','zxcvbnm'];
function keyboardMarkup(){const letter=c=>keyboardShift?c.toUpperCase():c;return `<div class="osk" aria-label="Dotyková klávesnice">${KEYBOARD_ROWS.map((row,i)=>`<div class="osk-row">${i===3?`<button type="button" class="osk-key osk-wide osk-shift" data-key="shift" aria-pressed="${keyboardShift}" aria-label="Shift">⇧</button>`:''}${[...row].map(c=>`<button type="button" class="osk-key" data-key="${letter(c)}">${letter(c)}</button>`).join('')}${i===3?'<button type="button" class="osk-key osk-wide osk-back" data-key="backspace" aria-label="Smazat znak">⌫</button>':''}</div>`).join('')}<div class="osk-row osk-bottom"><button type="button" class="osk-key osk-clear" data-key="clear">Smazat vše</button><button type="button" class="osk-key osk-space" data-key=" " aria-label="Mezera"></button><button type="submit" class="osk-key osk-enter" form="admin-login-form">Odemknout →</button></div></div>`}
function pressKey(key){const input=$('#admin-password');if(!input)return;lastActivity=Date.now();if(key==='shift'){keyboardShift=!keyboardShift;$('.osk').outerHTML=keyboardMarkup();input.focus();return}if(key==='backspace')input.value=input.value.slice(0,-1);else if(key==='clear')input.value='';else{input.value+=keyboardShift&&/^[a-z]$/.test(key)?key.toUpperCase():key;if(keyboardShift){keyboardShift=false;$('.osk').outerHTML=keyboardMarkup()}}$('#admin-login-error').textContent='';input.focus()}
function adminLogin(){
  if(adminAuthenticated){if($('#dialog').open)$('#dialog').close();staff();return}
  lastActivity=Date.now();
  keyboardShift=false;$('#dialog').classList.add('admin-dialog');
  $('#dialog-content').innerHTML=`<div class="admin-login-head"><img src="${logo}" alt=""><div><span class="eyebrow">POUZE PRO OBSLUHU</span><h1>Administrace</h1></div></div><div class="admin-login-body"><form id="admin-login-form"><label class="field-label" for="admin-password">Heslo obsluhy</label><input id="admin-password" type="password" required autocomplete="off" inputmode="none" placeholder="Zadej heslo na klávesnici níže"><p id="admin-login-error" role="alert"></p><button class="primary">Odemknout administraci →</button></form>${keyboardMarkup()}</div>`;
  $('#dialog').showModal();$('#admin-password').focus();
}
function unlockAdmin(){
  const password=$('#admin-password').value;$('#admin-password').value='';
  if(password!==ADMIN_PASSWORD){$('#admin-login-error').textContent='Nesprávné heslo. Zkus to znovu.';$('#admin-password').focus();return}
  adminAuthenticated=true;lastActivity=Date.now();$('#dialog').close();staff();
}
$('#dialog').addEventListener('submit',event=>{if(event.target.id==='admin-login-form'){event.preventDefault();unlockAdmin()}});
$('#dialog').addEventListener('click',event=>{const key=event.target.closest('[data-key]');if(key)pressKey(key.dataset.key)});
$('#dialog').addEventListener('close',()=>$('#dialog').classList.remove('admin-dialog'));
document.addEventListener('error',event=>{
  const image=event.target;
  if(!image.matches?.('.team-logo'))return;
  if(!image.dataset.retried&&image.dataset.remoteLogo){image.dataset.retried='true';image.src=image.dataset.remoteLogo;return}
  image.hidden=true;if(image.nextElementSibling)image.nextElementSibling.hidden=false;
},true);
$('#admin-access').onclick=adminLogin;
document.addEventListener('keydown',event=>{if(screen==='celebration'&&event.key==='Escape'){event.preventDefault();dismissCelebration()}});
$('#rules').onclick=rules;$('.close').onclick=()=>$('#dialog').close();
for(const type of ['pointerdown','keydown','input'])document.addEventListener(type,()=>lastActivity=Date.now());
let lastMatchPhase=closed(current())?'closed':started(current())?'open':'waiting';
setInterval(()=>{
  tickPartners();
  if(screen==='celebration'){if(celebration&&Date.now()>=celebration.expiresAt)dismissCelebration();return}
  if((screen!=='welcome'||adminAuthenticated||$('#dialog').open)&&Date.now()-lastActivity>90000)home();
  if(screen==='demo'&&demo?.playing&&Date.now()-demo.lastStepAt>=5000)advanceDemo();
  pollLive();refreshBoard();refreshParticipants();
  const m=current(),phase=closed(m)?'closed':started(m)?'open':'waiting';
  if($('#countdown'))$('#countdown').textContent=countdownText(m);
  if(lastMatchPhase&&phase!==lastMatchPhase){if(screen==='form')form();if(screen==='welcome')welcome();if(screen==='staff')staff()}
  lastMatchPhase=phase;
},1000);
addEventListener('hashchange',()=>location.hash==='#obsluha'?staff():home());
location.hash==='#obsluha'?staff():welcome();

